/* ============ 手动输入关键词 ============ */
function parseManualKeywords(text){
  if(!text) return [];
  // 优先按换行分割；单行时再按逗号/顿号/分号/制表分割
  let parts = text.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);
  if(parts.length<=1){
    parts = text.split(/[,，、;；\t]+/).map(s=>s.trim()).filter(Boolean);
  } else {
    parts = parts.flatMap(line=>{
      const seg=line.split(/[,，、;；\t]+/).map(s=>s.trim()).filter(Boolean);
      return seg.length?seg:[line];
    });
  }
  // 去重（保序）
  const seen=new Set(); const out=[];
  for(const p of parts){ if(!seen.has(p)){ seen.add(p); out.push(p); } }
  return out;
}
function updateKwCount(){
  const n=parseManualKeywords($('kwInput').value).length;
  $('kwCount').textContent=n+' 个关键词';
}
function ingestManualKeywords(){
  const kws=parseManualKeywords($('kwInput').value);
  if(!kws.length){ toast('请先输入至少一个关键词'); return; }
  ingest(kws.map(k=>[k]),'手动输入');
}

/* ============ 事件绑定 ============ */
function bind(){
  const dz=$('dropzone'); const fi=$('fileInput');
  dz.onclick=()=>fi.click();
  fi.onchange=()=>{ if(fi.files[0]) loadFile(fi.files[0]); fi.value=''; };
  ['dragenter','dragover'].forEach(e=>dz.addEventListener(e,ev=>{ev.preventDefault();dz.classList.add('hover');}));
  ['dragleave','drop'].forEach(e=>dz.addEventListener(e,ev=>{ev.preventDefault();dz.classList.remove('hover');}));
  dz.addEventListener('drop',ev=>{ const f=ev.dataTransfer.files[0]; if(f) loadFile(f); });

  $('loadSample').onclick=(e)=>{e.preventDefault(); loadSample();};

  $('kwInput').oninput=updateKwCount;
  $('kwInput').addEventListener('keydown',ev=>{ if((ev.ctrlKey||ev.metaKey)&&ev.key==='Enter'){ ev.preventDefault(); ingestManualKeywords(); } });
  $('btnKwClassify').onclick=ingestManualKeywords;
  $('btnKwClear').onclick=()=>{ $('kwInput').value=''; updateKwCount(); };
  $('btnReClass').onclick=()=>{
    readDictFromUI();
    if(state.mode==='ai'){ aiClassify(); } else { runClassification(); }
  };
  $('modeSeg').querySelectorAll('button').forEach(b=>{
    b.onclick=()=>{
      state.mode=b.dataset.mode;
      $('modeSeg').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));
      if(state.mode==='ai' && !state.ai.key){ toast('已切到 AI 增强：请在设置填写 API Key 后点重新分类'); }
    };
  });
  $('search').oninput=e=>{ state.search=e.target.value; renderTable(); };
  $('colSelect').onchange=e=>{ state.keywordCol=parseInt(e.target.value,10); runClassification(); };
  $('catFilter').onchange=e=>{ state.filterCat=e.target.value; renderLegend(); renderTable(); };
  $('onlyHit').onchange=()=>renderLegend();
  $('btnExport').onclick=exportXLSX;

  $('btnSettings').onclick=()=>{ fillDictTextareas(); $('drawer').classList.add('open'); $('drawerMask').style.display='block'; };
  $('drawerClose').onclick=closeDrawer;
  $('drawerMask').onclick=closeDrawer;
  $('resetDict').onclick=()=>{ state.dict={brand:[...BASE.brand],competitor:[...BASE.competitor],product:[...BASE.product],geo:[...BASE.geo],ext:{question:[],reputation:[],promo:[],price:[],attribute:[],audience:[]}}; fillDictTextareas(); toast('已重置为内置词典'); if(state.results.length) runClassification(); };
  $('confTh').oninput=e=>{ const v=parseInt(e.target.value,10); state.confTh=v; $('confThVal').textContent=v; renderTable(); };

  // 折叠：分类分布
  if(typeof document !== 'undefined' && typeof document.querySelectorAll === 'function'){
  document.querySelectorAll('.fold-h2').forEach(h2=>{
    const key = 'fold_' + h2.dataset.fold;
    if(localStorage.getItem(key) === '1') h2.classList.add('collapsed');
    h2.onclick = () => {
      h2.classList.toggle('collapsed');
      localStorage.setItem(key, h2.classList.contains('collapsed') ? '1' : '0');
    };
  });
  }
}
function closeDrawer(){ $('drawer').classList.remove('open'); $('drawerMask').style.display='none'; readDictFromUI(); renderTable(); }

